import { Effect, JsonSchema, Schema, Stream } from "effect";
import { tryRequest } from "./media-model.js";
import { LLMClient, Service } from "./route/client.js";
import { GenerationOptions, HttpOptions, InvalidProviderOutputError, AIError, LLMEvent, LLMRequest, LLMResponse, Message, LanguageModel, SystemPart, ToolChoice, ToolEntry, } from "./schema/index.js";
import { make as makeTool, toDefinitions } from "./tool.js";
import { ToolRuntime } from "./tool-runtime.js";
export function generate(input, options) {
    return requestEffect(input).pipe(Effect.flatMap((request) => LLMClient.generate(request, options)));
}
export function stream(input, options) {
    return Stream.unwrap(requestEffect(input).pipe(Effect.map((request) => LLMClient.stream(request, options))));
}
export function loop(input, options) {
    const { tools, until, ...rest } = input;
    const step = (request, steps) => Stream.suspend(() => {
        const events = [];
        return LLMClient.stream(request, options).pipe(Stream.map((event) => event.type === "step-start" || event.type === "step-finish" ? { ...event, index: steps.length } : event), Stream.tap((event) => Effect.sync(() => events.push(event))), Stream.concat(Stream.unwrap(Effect.gen(function* () {
            const response = LLMResponse.fromEvents(events);
            const calls = response?.toolCalls.filter((call) => call.providerExecuted !== true) ?? [];
            if (!response || calls.length === 0 || events.some(LLMEvent.is.providerError))
                return Stream.empty;
            const done = [...steps, response];
            if (until?.({ steps: done }))
                return Stream.empty;
            const results = yield* Effect.forEach(calls, (call) => ToolRuntime.dispatch(tools, call), {
                concurrency: "unbounded",
            });
            const next = LLMRequest.update(request, {
                messages: [
                    ...request.messages,
                    response.message,
                    ...calls.map((call, i) => Message.tool({
                        id: call.id,
                        name: call.name,
                        namespace: call.namespace,
                        result: results[i].result,
                        providerMetadata: call.providerMetadata,
                    })),
                ],
            });
            return Stream.fromIterable(results.flatMap((result) => result.events)).pipe(Stream.concat(step(next, done)));
        }))));
    });
    return Stream.unwrap(requestEffect({ ...rest, tools: toDefinitions(tools) }).pipe(Effect.map((request) => step(request, []))));
}
const requestEffect = (input) => input instanceof LLMRequest ? Effect.succeed(input) : tryRequest(() => request(input));
export const request = (input) => {
    const { system: requestSystem, prompt, messages, tools, toolChoice: requestToolChoice, generation: requestGeneration, providerOptions: requestProviderOptions, http: requestHttp, ...rest } = input;
    return new LLMRequest({
        ...rest,
        system: SystemPart.content(requestSystem),
        messages: [...(messages?.map(Message.make) ?? []), ...(prompt === undefined ? [] : [Message.user(prompt)])],
        tools: tools?.map(ToolEntry.make) ?? [],
        toolChoice: requestToolChoice ? ToolChoice.make(requestToolChoice) : undefined,
        generation: requestGeneration === undefined ? undefined : GenerationOptions.make(requestGeneration),
        providerOptions: requestProviderOptions,
        http: HttpOptions.make(requestHttp),
    });
};
const GENERATE_OBJECT_TOOL_NAME = "generate_object";
const GENERATE_OBJECT_TOOL_DESCRIPTION = "Return the structured result by calling this tool.";
export class GenerateObjectResponse {
    object;
    response;
    constructor(object, response) {
        this.object = object;
        this.response = response;
    }
    get events() {
        return this.response.events;
    }
    get usage() {
        return this.response.usage;
    }
}
const runGenerateObject = Effect.fn("LLM.generateObject")(function* (options, tool) {
    const baseRequest = request(options);
    const generateRequest = LLMRequest.update(baseRequest, {
        tools: toDefinitions({ [GENERATE_OBJECT_TOOL_NAME]: tool }),
        toolChoice: ToolChoice.named(GENERATE_OBJECT_TOOL_NAME),
    });
    const response = yield* LLMClient.generate(generateRequest);
    const call = response.toolCalls.find((event) => event.name === GENERATE_OBJECT_TOOL_NAME);
    if (!call)
        return yield* new AIError({
            reason: new InvalidProviderOutputError({
                message: `generateObject: model did not call the forced \`${GENERATE_OBJECT_TOOL_NAME}\` tool`,
            }),
        });
    const object = yield* tool._decode(call.input).pipe(Effect.mapError((error) => new AIError({
        reason: new InvalidProviderOutputError({
            message: `generateObject: tool input failed schema decode: ${error.message}`,
            cause: error,
        }),
    })));
    return new GenerateObjectResponse(object, response);
});
export function generateObject(options) {
    if ("schema" in options) {
        const { schema, ...rest } = options;
        return runGenerateObject(rest, makeTool({
            description: GENERATE_OBJECT_TOOL_DESCRIPTION,
            parameters: schema,
            success: Schema.Unknown,
            execute: () => Effect.void,
        }));
    }
    const { jsonSchema, ...rest } = options;
    return runGenerateObject(rest, makeTool({
        description: GENERATE_OBJECT_TOOL_DESCRIPTION,
        jsonSchema,
        execute: () => Effect.void,
    }));
}
